import {constellationNodes,schoolFor,learnedSchool} from './constellation-model.js';
export function buildBlueprint(state,id){const h=state.heroes[id],nodes=(state.skillGrid?.[id]||[]).filter(k=>k.startsWith('discipline:'));return {schema:'ash-aether.build-plan/1',hero:id,title:h.name+' · '+(h.doctrineSlots||[]).map(schoolFor).filter(Boolean).map(s=>{const learned=learnedSchool(state,id,s.id);return s.name+' '+(learned.economy?'Economy':'Surge')+' '+(learned.memory?'Memory':'Edge');}).join(' / '),nodes:[...nodes],schools:[...(h.doctrineSlots||[null,null])],recipes:(h.loadout||[]).map(x=>({core:x.core,support:x.support})),note:'A plan only. It grants no points, nodes, discoveries or equipment.'};}
export function validBlueprint(value){if(Array.isArray(value?.nodes)){const own=new Set(value.nodes),all=constellationNodes();for(const n of all.filter(n=>own.has(n.id))){const stem=`discipline:${n.school}:`;if(n.step==='surge'&&own.has(stem+'economy')||n.step==='cap'&&own.has(stem+'memory'))return false;if(n.requires!=='origin'&&!(Array.isArray(n.requires)?n.requires.some(r=>own.has(r)):own.has(n.requires)))return false;}}if(Array.isArray(value?.schools)){const selected=value.schools.filter(Boolean);if(selected.length!==new Set(selected).size||selected.reduce((n,k)=>n+(schoolFor(k)?.weight||0),0)>3)return false;}const known=new Set(constellationNodes().map(n=>n.id));return !!value&&value.schema==='ash-aether.build-plan/1'&&Number.isInteger(value.hero)&&value.hero>=0&&value.hero<7&&typeof value.title==='string'&&value.title.length<=150&&Array.isArray(value.nodes)&&value.nodes.length<=72&&new Set(value.nodes).size===value.nodes.length&&value.nodes.every(k=>known.has(k))&&Array.isArray(value.schools)&&value.schools.length<=2&&value.schools.every(k=>k===null||!!schoolFor(k));}
export function blueprintProgress(plan,state){if(!validBlueprint(plan))return null;const own=new Set(state.skillGrid?.[plan.hero]||[]),nodes=constellationNodes().filter(n=>plan.nodes.includes(n.id));return{learned:nodes.filter(n=>own.has(n.id)).length,total:nodes.length,remainingCost:nodes.filter(n=>!own.has(n.id)).reduce((v,n)=>v+n.cost,0),lastChapter:nodes.reduce((v,n)=>Math.max(v,n.chapter),1)};}
